ck to explore each role. All use <code>Sikhaya2026!</code></p><div class="demo-buttons"><?php foreach(['buyer'=>['Buyer','buyer@sikhaya.example'],'artist'=>['Artist','artist@sikhaya.example'],'admin'=>['Admin','admin@sikhaya.example']] as $r=>$v):form('login',['email'=>$v[1],'password'=>'Sikhaya2026!']);?><button class="btn btn-outline full" type="submit"><?=icon($r==='artist'?'pen':($r==='admin'?'settings':'bag'))?> <?=$v[0]?></button></form><?php endforeach;?></div><small>buyer@sikhaya.example · artist@sikhaya.example · admin@sikhaya.example</small></div><?php endif;?></div></div><?php
