function profile():void{
    $u=need_user();page_heading('YOUR SPACE','Make yourself at home.','Your profile, your words, your next chapter.');
    echo '<div class="two-columns"><section class="panel">';form('profile');?><label>Display name<input name="display_name" value="<?=e($u['display_name'])?>" maxlength="80" required></label><label>Region or city<input name="region" value="<?=e($u['region'])?>" maxlength="80"></label><label>About you<textarea name="bio" maxlength="2000"><?=e($u['bio'])?></textarea></label><details><summary>Change password</summary><label>Current password<input name="current_password" type="password" autocomplete="current-password"></label><label>New password<input name="new_password" type="password" minlength="8" autocomplete="new-password"></label></details><button class="btn">Save profile <?=icon('check')?></button></form></section><aside class="panel"><h2><?=e($u['display_name'])?></h2><?=status($u['role'])?><p><?=e($u['email'])?></p><?php if($u['role']==='buyer'):?><h3>Have a little art to share?</h3><p>Open an artist profile, build your portfolio, and bring your work to the community.</p><?php action_button('become_artist',[],'Open my artist profile','btn btn-outline');else:?><a class="btn btn-outline" href="<?=url($u['role']==='admin'?'admin':'studio')?>">Open workspace <?=icon('arrow')?></a><?php endif;echo '<hr>';action_button('logout',[],icon('logout').' Sign out','btn btn-outline');echo '</aside></div>';
}
function cart(bool $checkout=false):void{
    $u=need_user();$rows=all('SELECT c.*,l.title,l.unit_price_centavos,l.stock_qty,l.seller_id,l.artwork_id,l.section,l.status,u.display_name FROM cart_items c JOIN listings l ON l.id=c.listing_id JOIN users u ON u.id=l.seller_id WHERE buyer_id=?',[$u['id']]);page_heading('YOUR COLLECTION IN THE MAKING',$checkout?'One step closer to a new favorite.':'A few good finds.','No real money is charged. This checkout is for the school prototype.');if(!$rows){empty_state('Your bag has room for inspiration.','Find a piece of art or a new studio essential.');return;}
    $total=0;echo '<div class="checkout-layout"><div class="panel cart-list">';foreach($rows as $r){$l=listing((int)$r['listing_id']);$subtotal=$r['quantity']*$r['unit_price_centavos'];$total+=$subtotal;echo '<article class="cart-row"><a class="cart-thumb" href="'.url('detail',['id'=>$l['id']]).'">';visual_media(listing_media($l));echo '</a><div><span class="eyebrow">'.e(SECTIONS[$l['section']][0]).'</span><h2>'.e($r['title']).'</h2><p>By '.e($r['display_name']).'</p><strong>'.money((int)$r['unit_price_centavos']).'</strong></div>';form('cart_update',['id'=>$r['id']],'cart-qty');echo '<label>Quantity<input name="quantity" type="number" min="0" max="9999" value="'.$r['quantity'].'"></label><button class="text-button">Update</button><small>0 removes item</small></form><strong>'.money((int)$subtotal).'</strong></article>';}
    echo '</div><aside class="panel order-summary"><span class="eyebrow">YOUR ORDER</span><h2>A little more local.</h2><div class="simple-row"><span>Items</span><strong>'.money($total).'</strong></div><div class="simple-row"><span>Simulated pickup</span><span>No charge</span></div><div class="summary-total"><span>Total</span><strong>'.money($total).'</strong></div>';
    if($checkout){form('checkout',['request_token'=>bin2hex(random_bytes(20))]);foreach($rows as $r)echo '<input type="hidden" name="prices['.$r['listing_id'].']" value="'.$r['unit_price_centavos'].'">';echo '<label>Pickup notes<textarea name="pickup_notes" maxlength="1000" placeholder="A demo pickup arrangement. No real address needed."></textarea></label><button class="btn full">Confirm fake checkout '.icon('check').'</button></form><p class="form-hint">No bank details. No payment gateway. A saved demo receipt is created.</p>';}else echo '<a class="btn full" href="'.url('checkout').'">Review checkout '.icon('arrow').'</a>';
    echo '<a class="text-link" href="'.url('catalog').'">Keep exploring</a></aside></div>';
}
function orders():void{
    $u=need_user();page_heading('YOUR SIKHAYA JOURNEY','Good things, finding their way.','Orders, demo receipts, and what happens next.');$args=[$u['id'],$u['id']];$sql='SELECT DISTINCT o.* FROM orders o JOIN order_items i ON i.order_id=o.id WHERE (o.buyer_id=? OR i.seller_id=?)';if(!empty($_GET['id'])){$sql.=' AND o.id=?';$args[]=(int)$_GET['id'];}$rows=all($sql.' ORDER BY o.id DESC',$args);if(!$rows){empty_state('No orders yet.','Your first discovery is waiting in the collection.');return;}
    foreach($rows as $o){$buyer=$o['buyer_id']===$u['id'];echo '<section class="panel order-panel"><div class="panel-heading"><div><span class="eyebrow">'.e($o['order_number']).' / '.e($o['source']).'</span><h2>'.($buyer?'Your order':'Studio sale').'</h2></div>'.status($o['payment_status']).'</div>';foreach(all('SELECT * FROM order_items WHERE order_id=?'.($buyer?'':' AND seller_id=?'),$buyer?[$o['id']]:[$o['id'],$u['id']]) as $i){echo '<div class="order-line"><div><a href="'.url('detail',['id'=>$i['listing_id']]).'"><strong>'.e($i['item_title']).'</strong></a><p>'.$i['quantity'].' × '.money((int)$i['unit_price_centavos']).' · '.status($i['status']).'</p>'.($i['platform_fee_centavos']?'<small>Rental platform fee: '.money((int)$i['platform_fee_centavos']).' · Provider net: '.money((int)$i['seller_net_centavos']).'</small>':'').'</div><strong>'.money((int)$i['line_total_centavos']).'</strong>';if($i['seller_id']===$u['id']&&$o['payment_status']==='demo_paid'&&!$i['rental_booking_id']&&!$i['commission_request_id']){if($i['status']==='confirmed')action_button('fulfill',['id'=>$i['id'],'step'=>'ready'],'Mark ready','btn btn-small btn-outline');if($i['status']==='ready')action_button('fulfill',['id'=>$i['id'],'step'=>'completed'],'Complete pickup','btn btn-small');}echo '</div>';}
        if($buyer)echo '<div class="simple-row"><span>Demo order total</span><strong>'.money((int)$o['total_centavos']).'</strong></div><p class="form-hint">'.e($o['recipient_name']).' · Simulated pickup · '.e($o['pickup_notes']).'</p>';
        if($buyer&&$o['payment_status']==='awaiting_demo_payment'){echo '<p>Winner checkout closes '.date('M j, g:i A',strtotime($o['payment_due_at'])).' PHT. No money is charged.</p>';action_button('special_pay',['id'=>$o['id'],'type'=>'auction','request_token'=>bin2hex(random_bytes(20))],'Confirm fake winner checkout '.icon('check'));}
        echo '<small>'.($o['demo_paid_at']?'Demo payment saved '.date('M j, Y · g:i A',strtotime($o['demo_paid_at'])).' PHT':'No payment recorded').'</small></section>';
    }
    echo '<div class="section-heading"><h2>Your bidding history</h2></div><div class="panel">';$bids=all('SELECT b.*,a.winning_bid_id,a.status,l.title,l.id AS listing FROM bids b JOIN auctions a ON a.id=b.auction_id JOIN listings l ON l.id=a.listing_id WHERE bidder_id=? ORDER BY b.id DESC LIMIT 30',[$u['id']]);if(!$bids)echo '<p class="muted">No bids yet.</p>';foreach($bids as $b){$high=one('SELECT bidder_id FROM bids WHERE auction_id=? ORDER BY amount_centavos DESC,id LIMIT 1',[$b['auction_id']]);$state=$b['status']==='ended'?($b['winning_bid_id']===$b['id']?'Won':'Ended'):($high['bidder_id']===$u['id']?'Leading':'Outbid');echo '<div class="simple-row"><a href="'.url('detail',['id'=>$b['listing']]).'">'.e($b['title']).'</a><span>'.money((int)$b['amount_centavos']).' · '.$state.'</span></div>';}echo '</div>';
}
function work():void{
    $u=need_user();page_heading('CREATIVE PLANS, COMING TO LIFE','A little work in progress.','Your rentals and custom-art projects, in one place.');$rentals=all('SELECT r.*,l.title,l.seller_id,u.display_name AS renter FROM rental_bookings r JOIN listings l ON l.id=r.listing_id JOIN users u ON u.id=r.renter_id WHERE r.renter_id=? OR l.seller_id=? ORDER BY r.id DESC',[$u['id'],$u['id']]);echo '<div class="section-heading"><h2>Equipment rentals</h2><a class="text-link" href="'.url('catalog',['section'=>'arkilikha']).'">Find equipment '.icon('arrow').'</a></div>';if(!$rentals)echo '<div class="panel muted">No rentals yet. Find the right tools for your next idea.</div>';
    foreach($rentals as $r){$owner=$r['seller_id']===$u['id'];echo '<section class="panel work-card"><div class="panel-heading"><div><span class="eyebrow">RENTAL #'.$r['id'].' · '.($owner?'STUDIO REQUEST':'YOUR BOOKING').'</span><h2>'.e($r['title']).'</h2></div>'.status($r['status']).'</div><div class="work-facts"><span><small>Pickup → Return</small><strong>'.e($r['start_date']).' → '.e($r['end_date']).'</strong></span><span><small>Rental total</small><strong>'.money((int)$r['rental_total_centavos']).' / '.$r['days'].' days</strong></span><span><small>Provider commission</small><strong>'.($r['commission_bps']/100).'% · '.money((int)$r['platform_fee_centavos']).'</strong></span></div><p class="form-hint">Requested by '.e($r['renter']).'. Return date is excluded. Fee is deducted from provider proceeds.</p><div class="button-row">';
        if($owner&&$r['status']==='requested'){action_button('rental_step',['id'=>$r['id'],'step'=>'approve'],'Approve dates');action_button('rental_step',['id'=>$r['id'],'step'=>'reject'],'Decline','btn btn-outline');}
        if(!$owner&&$r['status']==='approved'){echo '<p class="notice">Reserved until '.date('M j, g:i A',strtotime($r['hold_expires_at'])).' PHT. No real payment.</p>';action_button('special_pay',['id'=>$r['id'],'type'=>'rental','request_token'=>bin2hex(random_bytes(20))],'Confirm fake checkout '.icon('check'));}
        if(!$owner&&in_array($r['status'],['requested','approved']))action_button('rental_step',['id'=>$r['id'],'step'=>'cancel'],'Cancel request','btn btn-outline');
        if($owner&&$r['status']==='confirmed')action_button('rental_step',['id'=>$r['id'],'step'=>'collect'],'Record equipment pickup');if($owner&&$r['status']==='collected')action_button('rental_step',['id'=>$r['id'],'step'=>'return'],'Record equipment return');echo '</div></section>';
    }
    echo '<div class="section-heading"><h2>Custom-art commissions</h2><a class="text-link" href="'.url('catalog',['section'=>'gawang_hiling']).'">Find an artist '.icon('arrow').'</a></div>';
    $rows=all('SELECT r.*,l.title,l.seller_id,u.display_name AS buyer FROM commission_requests r JOIN listings l ON l.id=r.offer_listing_id JOIN users u ON u.id=r.buyer_id WHERE r.buyer_id=? OR l.seller_id=? ORDER BY r.id DESC',[$u['id'],$u['id']]);if(!$rows)echo '<div class="panel muted">No commission projects yet. Your next idea can start here.</div>';
    foreach($rows as $r){$owner=$r['seller_id']===$u['id'];echo '<section class="panel work-card" id="commission-'.$r['id'].'"><div class="panel-heading"><div><span class="eyebrow">CUSTOM ART #'.$r['id'].' · '.e($r['buyer']).'</span><h2>'.e($r['title']).'</h2></div>'.status($r['status']).'</div><p>'.nl2br(e($r['brief'])).'</p>';if($r['reference_media_id'])echo '<a class="text-link" href="/image.php?id='.$r['reference_media_id'].'">View private reference image</a>';if($r['quoted_price_centavos'])echo '<div class="work-facts"><span><small>Artist quote</small><strong>'.money((int)$r['quoted_price_centavos']).'</strong></span><span><small>Agreed delivery</small><strong>'.e($r['quoted_due_date']).'</strong></span><span><small>Revisions used</small><strong>'.$r['revisions_used'].' / '.$r['agreed_revision_limit'].'</strong></span></div>';
        if($owner&&in_array($r['status'],['requested','quoted'])){form('commission_step',['id'=>$r['id'],'step'=>'quote'],'quote-form');echo '<div class="form-row"><label>Quote price (PHP)<input name="price" type="number" min="1" step="0.01" value="'.(($r['quoted_price_centavos']??300000)/100).'" required></label><label>Delivery date<input name="due_date" type="date" min="'.date('Y-m-d').'" value="'.e($r['quoted_due_date']??date('Y-m-d',strtotime('+14 days'))).'" required></label></div><button class="btn btn-small">Send quote</button></form>';}
        echo '<div class="button-row">';if(!$owner&&$r['status']==='quoted'){action_button('commission_step',['id'=>$r['id'],'step'=>'accept'],'Accept quote');action_button('commission_step',['id'=>$r['id'],'step'=>'cancel'],'Decline','btn btn-outline');}
        if(!$owner&&$r['status']==='accepted')action_button('special_pay',['id'=>$r['id'],'type'=>'commission','request_token'=>bin2hex(random_bytes(20))],'Confirm fake checkout '.icon('check'));
        if($owner&&in_array($r['status'],['requested','quoted']))action_button('commission_step',['id'=>$r['id'],'step'=>'reject'],'Decline project','btn btn-outline');
        if($owner&&$r['status']==='in_progress')action_button('commission_step',['id'=>$r['id'],'step'=>'deliver'],'Mark artwork delivered');
        if(!$owner&&$r['status']==='delivered')action_button('commission_step',['id'=>$r['id'],'step'=>'complete'],'Accept final artwork '.icon('check'));
        if(!$owner&&in_array($r['status'],['requested','accepted']))action_button('commission_step',['id'=>$r['id'],'step'=>'cancel'],'Cancel request','btn btn-outline');echo '</div>';
        if(!$owner&&$r['status']==='delivered'&&$r['revisions_used']<$r['agreed_revision_limit']){form('commission_step',['id'=>$r['id'],'step'=>'revision']);echo '<label>Request a revision<textarea name="body" required maxlength="4000"></textarea></label><button class="btn btn-small btn-outline">Send revision request</button></form>';}
        echo '<details class="project-thread"><summary>Private project conversation</summary>';foreach(all('SELECT m.*,u.display_name FROM commission_messages m JOIN users u ON u.id=m.author_id WHERE request_id=? ORDER BY m.id',[$r['id']]) as $m){echo '<div class="thread-message"><strong>'.e($m['display_name']).'</strong><p>'.nl2br(e($m['body'])).'</p>';if($m['attachment_media_id'])echo '<a class="text-link" href="/image.php?id='.$m['attachment_media_id'].'">View private image</a>';echo '</div>';}
        ?><form method="post" action="/" enctype="multipart/form-data"><?=token_field()?><input type="hidden" name="action" value="message"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="return" value="<?=e($_SERVER['REQUEST_URI'])?>"><label>Message or progress note<textarea name="body" maxlength="4000" required></textarea></label><label>Reference, progress, or delivery image<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><button class="btn btn-small btn-outline">Send private update</button></form></details></section><?php
    }
}
function feed():void{
    $u=user();page_heading('THE COMMUNITY STUDIO','A space to share your spark.','Works in progress, little discoveries, and the people making them.');echo '<div class="feed-layout"><div class="feed-column">';
    if($u){?><details class="panel composer" open><summary><?=avatar($u['display_name'])?> What are you creating, <?=e(explode(' ',$u['display_name'])[0])?>?</summary><form method="post" action="/" enctype="multipart/form-data"><?=token_field()?><input type="hidden" name="action" value="post_create"><input type="hidden" name="return" value="/?p=feed"><label class="sr-only" for="post-body">Post description</label><textarea id="post-body" name="body" maxlength="3000" required placeholder="A little story behind your work…"></textarea><div class="composer-bottom"><label class="file-label"><?=icon('gallery')?> Add artwork image<input type="file" name="images[]" accept="image/jpeg,image/png,image/webp" multiple required></label><button class="btn btn-small">Share your work <?=icon('plus')?></button></div></form></details><?php }else echo '<div class="panel"><a class="text-link" href="'.url('login').'">Sign in to share your work and join the conversation '.icon('arrow').'</a></div>';
    $page=max(1,(int)($_GET['page']??1));$only=(int)($_GET['post']??0);$sql="SELECT p.*,u.display_name,u.region FROM posts p JOIN users u ON u.id=p.author_id WHERE p.status='visible' AND u.status='active'";$args=[];if($only){$sql.=' AND p.id=?';$args[]=$only;}$sql.=' ORDER BY p.created_at DESC,p.id DESC LIMIT 6 OFFSET '.(($page-1)*6);$posts=all($sql,$args);
    foreach($posts as $p){$original=$p['shared_post_id']?one("SELECT p.*,u.display_name FROM posts p JOIN users u ON u.id=p.author_id WHERE p.id=? AND p.status='visible' AND u.status='active'",[$p['shared_post_id']]):$p;echo '<article class="feed-post panel" id="post-'.$p['id'].'"><div class="post-header">'.avatar($p['display_name']).'<div><a href="'.url('artist',['id'=>$p['author_id']]).'"><strong>'.e($p['display_name']).'</strong></a><small>'.e($p['region']).' · '.date('M j, g:i A',strtotime($p['created_at'])).'</small></div>';if($p['shared_post_id'])echo '<span class="status">Shared a work</span>';echo '</div>';if($p['body'])echo '<p class="post-body">'.nl2br(e($p['body'])).'</p>';
        if($original){if($p['shared_post_id'])echo '<div class="shared-label">Originally shared by <strong>'.e($original['display_name']).'</strong><p>'.e($original['body']).'</p></div>';echo '<div class="post-gallery">';foreach(all('SELECT m.* FROM media m JOIN post_images i ON i.media_id=m.id WHERE i.post_id=? ORDER BY sort_order',[$original['id']]) as $m)visual_media($m);echo '</div>';}else echo '<div class="unavailable">The original post is no longer available.</div>';
        $reacts=all('SELECT reaction,COUNT(*) AS n FROM post_reactions WHERE post_id=? GROUP BY reaction',[$p['id']]);echo '<div class="post-counts"><span>';foreach($reacts as $r)echo e(ucfirst($r['reaction'])).' '.$r['n'].' &nbsp;';echo '</span><a href="#comments-'.$p['id'].'">'.query("SELECT COUNT(*) FROM comments WHERE post_id=? AND status='visible'",[$p['id']])->fetchColumn().' comments</a></div><div class="post-actions">';$mine=$u?one('SELECT reaction FROM post_reactions WHERE post_id=? AND user_id=?',[$p['id'],$u['id']]):null;foreach(['like'=>'♡ Like','love'=>'♥ Love','wow'=>'✦ Wow'] as $r=>$label)action_button('react',['id'=>$p['id'],'reaction'=>$r],$label,'reaction '.(($mine['reaction']??'')===$r?'selected':''));action_button('share',['id'=>$p['id']],icon('share').' Share','reaction');action_button('save',['id'=>$p['id'],'type'=>'post'],icon('bookmark').' Save','reaction');echo '<button class="reaction" data-copy="'.e(url('feed',['post'=>$p['id']])).'">Copy link</button></div><div class="comments" id="comments-'.$p['id'].'">';
        foreach(all('SELECT c.*,u.display_name FROM comments c JOIN users u ON u.id=c.author_id WHERE c.post_id=? ORDER BY COALESCE(c.parent_comment_id,c.id),c.id',[$p['id']]) as $c){echo '<div class="comment '.($c['parent_comment_id']?'reply':'').'">'.avatar($c['display_name']).'<div><strong>'.e($c['display_name']).'</strong><p>'.($c['status']==='visible'?e($c['body']):'Comment removed.').'</p>';if($u&&$c['status']==='visible'){if($c['author_id']===$u['id'])action_button('comment_delete',['id'=>$c['id']],'Delete','text-button');if(!$c['parent_comment_id']){echo '<details><summary class="small-summary">Reply</summary>';form('comment',['id'=>$p['id'],'parent'=>$c['id']]);echo '<label class="sr-only">Reply text</label><input name="body" maxlength="1500" aria-label="Write a reply" required placeholder="Write a reply"><button class="text-button">Reply</button></form></details>';}}echo '</div></div>';}
        if($u){form('comment',['id'=>$p['id']],'comment-form');echo avatar($u['display_name']).'<label class="sr-only">Comment</label><input name="body" required maxlength="1500" aria-label="Write a comment" placeholder="Leave a little encouragement…"><button aria-label="Post comment" class="icon-button">'.icon('arrow').'</button></form>';}
        echo '</div><details class="post-options"><summary>Post options</summary><div class="button-row">';if($u&&$p['author_id']===$u['id']){action_button('post_delete',['id'=>$p['id']],'Delete my post','btn btn-small btn-outline');if(!$p['shared_post_id']){form('post_edit',['id'=>$p['id']]);echo '<label>Edit description<textarea name="body" maxlength="3000" required>'.e($p['body']).'</textarea></label><button class="btn btn-small btn-outline">Save description</button></form>';}}form('report',['id'=>$p['id'],'type'=>'post']);echo '<label>Report reason<input name="reason" maxlength="1000" required></label><button class="text-button">Send report</button></form></div></details></article>';
    }
    if(!$posts)empty_state('A quiet moment in the studio.','Be the first to share something.','feed');if(!$only){echo '<nav class="pagination" aria-label="Feed pages">';$count=(int)query("SELECT COUNT(*) FROM posts WHERE status='visible'")->fetchColumn();for($i=1;$i<=ceil($count/6);$i++)echo '<a class="'.($i===$page?'selected':'').'" href="'.url('feed',['page'=>$i]).'">'.$i.'</a>';echo '</nav>';}
    echo '</div><aside class="feed-aside"><div class="panel"><span class="eyebrow">A LITTLE STUDIO ETIQUETTE</span><h2>Make room for<br>each other.</h2><p>Share work you have permission to share. Give credit. Be kind with your words. There’s room for every creative journey.</p><a class="text-link" href="'.url('help').'">Community & marketplace guide '.icon('arrow').'</a></div><div class="panel"><span class="eyebrow">MEET THE MAKERS</span>';foreach(all('SELECT u.*,a.badge FROM users u JOIN artist_profiles a ON a.user_id=u.id LIMIT 4') as $a)echo '<a class="maker-row" href="'.url('artist',['id'=>$a['id']]).'">'.avatar($a['display_name']).'<span><strong>'.e($a['display_name']).'</strong><small>'.e($a['region']).'</small></span>'.icon('arrow').'</a>';echo '</div><p class="form-hint">Fictional community posts and generated sample art are included for the school demo.</p></aside></div>';
}
function saved():void{
    $u=need_user();page_heading('YOUR SAVED COLLECTION','Keep a little inspiration close.','Art, artists, and conversations you want to come back to.');$saves=all('SELECT * FROM saved_items WHERE user_id=? ORDER BY id DESC',[$u['id']]);if(!$saves){empty_state('A collection starts with one good find.','Tap the heart or save button on something you love.');return;}
    echo '<div class="art-grid">';foreach($saves as $s){if($s['listing_id']){$l=listing((int)$s['listing_id']);if(in_array($l['status'],['published','sold_out'])&&(!$l['artwork_id']||$l['artwork_status']==='visible')){card($l);continue;}$title='Listing unavailable';$type='listing';$id=$s['listing_id'];$link='';}
        elseif($s['artist_id']){$a=one('SELECT display_name FROM users WHERE id=? AND status=\'active\'',[$s['artist_id']]);$title=$a['display_name']??'Artist unavailable';$type='artist';$id=$s['artist_id'];$link=$a?url('artist',['id'=>$id]):'';}
        elseif($s['post_id']){$a=one("SELECT body FROM posts WHERE id=? AND status='visible'",[$s['post_id']]);$title=$a?mb_strimwidth($a['body'],0,90,'…'):'Post unavailable';$type='post';$id=$s['post_id'];$link=$a?url('feed',['post'=>$id]):'';}
        else{$a=one("SELECT title FROM artworks WHERE id=? AND status='visible'",[$s['artwork_id']]);$title=$a['title']??'Artwork unavailable';$type='artwork';$id=$s['artwork_id'];$link=$a?url('artwork',['id'=>$id]):'';}
        echo '<article class="panel saved-card">'.icon($type==='artist'?'user':'bookmark').'<span class="eyebrow">'.e($type).'</span><h2>'.e($title).'</h2>';if($link)echo '<a class="text-link" href="'.e($link).'">Open saved item '.icon('arrow').'</a>';action_button('save',['id'=>$id,'type'=>$type],'Remove save','btn btn-small btn-outline');echo '</article>';}
    echo '</div>';
}
